import 'package:collection/collection.dart';

class Transaction {
  final String coinName;
  final DateTime datetime;
  final double profitEarnedOrLoss;

  const Transaction({required this.coinName, required this.datetime, required this.profitEarnedOrLoss});
}

List<Transaction> sortTransactionsByProfit(List<Transaction> transactions) {
  return transactions.sort((a, b) => b.profitEarnedOrLoss.compareTo(a.profitEarnedOrLoss));
}

List<Transaction> sortTransactionsByLoss(List<Transaction> transactions) {
  return transactions.sort((a, b) => a.profitEarnedOrLoss.compareTo(b.profitEarnedOrLoss));
}

