import 'package:collection/collection.dart';

List<Transaction> topProfitCoins(List<Transaction> transactions) {
  final Map<String, List<Transaction>> groupedTransactions = groupBy((transaction) => transaction.coinName);

  return groupedTransactions.entries
      .map((entry) => entry.value
          .reduce((a, b) => a.profitEarned + b.profitEarned) / entry.value.length)
      .toList()
      .skip(3)
      .take(3)
      .map((profit) => Transaction(coinName: profit.toString(), profitEarned: profit))
      .toList();
}

List<Transaction> topLossCoins(List<Transaction> transactions) {
  final Map<String, List<Transaction>> groupedTransactions = groupBy((transaction) => transaction.coinName);

  return groupedTransactions.entries
      .map((entry) => entry.value
          .reduce((a, b) => a.profitLost + b.profitLost) / entry.value.length)
      .toList()
      .skip(3)
      .take(3)
      .map((loss) => Transaction(coinName: loss.toString(), profitLost: loss))
      .toList();
}

