```dart
import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime datetime;
  final double profitEarnedLoss;

  Transaction({required this.coinName, required this.datetime, required this.profitEarnedLoss});
}

List<Transaction> sortTransactionsByProfit(List<Transaction> transactions) {
  return transactions.sort((a, b) => b.profitEarnedLoss.compareTo(a.profitEarnedLoss));
}

List<Transaction> sortTransactionsByAverageProfit(List<Transaction> transactions) {
  var totalProfit = 0.0;
  var count = 0;

  for (var transaction in transactions) {
    totalProfit += transaction.profitEarnedLoss;
    count++;
  }

  var averageProfit = totalProfit / count;
  return transactions.map((transaction) => Transaction(coinName: transaction.coinName, datetime: transaction.datetime, profitEarnedLoss: transaction.profitEarnedLoss - averageProfit)).toList();
}

List<Transaction> sortTransactionsByLoss(List<Transaction> transactions) {
  return transactions.sort((a, b) => a.profitEarnedLoss.compareTo(b.profitEarnedLoss));
}

List<Transaction> sortTransactionsByAverageLoss(List<Transaction> transactions) {
  var totalLoss = 0.0;
  var count = 0;

  for (var transaction in transactions) {
    totalLoss += transaction.profitEarnedLoss;
    count++;
  }

  var averageLoss = totalLoss / count;
  return transactions.map((transaction) => Transaction(coinName: transaction.coinName, datetime: transaction.datetime, profitEarnedLoss: transaction.profitEarnedLoss - averageLoss)).toList();
}

