Here is an example of an LDPC (Low-Density Parity-Check) encoder module written in SystemVerilog for FPGA implementation:
```verilog
module ldpc_encoder(
    input wire clk,
    input wire reset,
    input wire data_in[],
    output wire data_out[]
);

// Define the LDPC code parameters
parameter int num_bits = 8; // Number of bits per symbol
parameter int num_symbols = 1024; // Number of symbols
parameter int num_parity_bits = 16; // Number of parity bits

// Define the LDPC generator matrix
logic [num_bits - 1:0] gm[num_symbols][num_parity_bits];

// Initialize the LDPC generator matrix
initial begin
    for (int i = 0; i < num_symbols; i++) {
        for (int j = 0; j < num_parity_bits; j++) {
            gm[i][j] = random();
        }
    }
end

// Encode the input data using the LDPC code
always @(posedge clk or posedge reset)
begin
    if (reset) {
        for (int i = 0; i < num_symbols; i++) {
            data_out[i] = 0;
        }
    } else {
        for (int i = 0; i < num_symbols; i++) {
            logic [num_bits - 1:0] symbol = data_in[i];
            logic [num_parity_bits - 1:0] parity = 0;

            for (int j = 0; j < num_parity_bits; j++) {
                parity[j] = gm[i][j] ^ symbol[j];
            }

            data_out[i] = parity;
        }
    }
end

endmodule
```
