```verilog
module ldpc_encoder(
    input wire clk,
    input wire reset,
    input wire data_in,
    output wire data_out
);

reg [7:0] data_reg;
reg [31:0] parity_reg;

always @(posedge clk or posedge reset)
begin
    if (reset)
    begin
        data_reg <= 8'b00000000;
        parity_reg <= 32'b00000000000000000000000000000000;
    end
