```javascript
import React, { useState } from 'react';
import { ScrollView, Text, View } from 'react-native';

const CustomScrollView = ({ children }) => {
  const [currentSection, setCurrentSection] = useState(0);

  const handleScroll = (event) => {
    const offset = event.nativeEvent.contentOffset.y;
    const height = event.nativeEvent.layoutMeasurement.height;

    if (offset >= height - 100) {
      // Prevent scrolling past the last focused section
      event.preventDefault();
    }
  };

  const handleFocusChange = (section) => {
    setCurrentSection(section);
  };

  const renderSection = (section) => {
    return (
      <View key={section} style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>
        <Text style={{ fontSize: 18, color: currentSection === section ? 'black' : 'gray' }}>Section {section}</Text>
        <button title="Complete Task" onPress={() => handleFocusChange(section + 1)} />
      </View>
    );
  };

  return (
    <ScrollView onScroll={handleScroll}>
      {children.map(renderSection)}
    </ScrollView>
  );
};

export default CustomScrollView;
```

