    var rating: Int
    var reviewText: String
}

class StatementGenerator {
    func generateStatement(for userPreferences: UserPreferences, productReviews: [ProductReview]) -> String {
        var statement = "Based on your preferences, we recommend the following products:"

        // Add products that match the user's favorite colors
        if !userPreferences.favoriteColors.isEmpty {
            statement += "\nProducts in your favorite colors:"
