                if let products = productReviews.filter({ $0.product.color == color }) {
                    statement += "\n\t- \(products.first?.product.name ?? "")"
                }
            }
        }

        // Add products that match the user's preferred product categories
        if !userPreferences.preferredProductCategories.isEmpty {
            statement += "\nProducts in your preferred categories:"
            for category in userPreferences.preferredProductCategories {
                if let products = productReviews.filter({ $0.product.category == category }) {
                    statement += "\n\t- \(products.first?.product.name ?? "")"
                }
            }
        }

        // Add products with high ratings and positive reviews
        statement += "\nTop-rated products with positive reviews:"
        for review in productReviews {
            if review.rating >= 4 && review.reviewText.contains("positive") {
                statement += "\n\t- \(review.product.name)"
            }
        }

        return statement
    }
}

