Here's an After Effects script that creates a vertical video by stacking two other videos on top of each other vertically, and adding subtitles to the top half of the video with the given text file/script. Make sure you have the required files in a folder on your desktop that After Effects can access.

```javascript
// Load the required files
var file1 = File.openDialog("Select the first video file");
var file2 = File.openDialog("Select the second video file");
var textFile = File.openDialog("Select the text file containing subtitles");

// Create a new composition
var comp = app.activeComposition;
comp.name = "Vertical Video";
comp.duration = Math.max(file1.duration, file2.duration);

// Import the video files into the composition
var layer1 = comp.layers.add(file1);
var layer2 = comp.layers.add(file2);

// Stack the video layers vertically
layer1.transform.position.y = -layer1.height;
layer2.transform.position.y = layer1.height;

// Add subtitles to the top half of the video
var subtitleLayer = comp.layers.addText();
subtitleLayer.text = textFile.read();
subtitleLayer.transform.position.y = -subtitleLayer.height / 2;

// Adjust the layer opacity and blend mode
layer1.opacity = 0.5;
layer1.blendMode = BlendMode.MULTIPLY;
layer2.opacity = 0.5;
layer2.blendMode = BlendMode.MULTIPLY;
subtitleLayer.opacity = 1;
subtitleLayer.blendMode = BlendMode.NONE;

// Export the final composition
comp.export("vertical_video.mp4");
```

