```matlab
function tense = identify_tense(sentence)
    % Split the sentence into words
    words = split(sentence);

    % Check for common indicators of past tense (e.g., "had" or "would have")
    for i = 1:numel(words)
        if strcmpi(words{i}, 'had') || strcmpi(words{i}, 'would have')
            tense = 'past';
            break;
        end
    end

    % Check for common indicators of future tense (e.g., "will" or "shall")
    for i = 1:numel(words)
        if strcmpi(words{i}, 'will') || strcmpi(words{i}, 'shall')
            tense = 'future';
            break;
        end
    end

    % Check for common indicators of present tense (e.g., "is", "are", or "be")
    for i = 1:numel(words)
        if strcmpi(words{i}, 'is') || strcmpi(words{i}, 'are') || strcmpi(words{i}, 'be')
            tense = 'present';
            break;
        end
    end

    % If none of the above conditions are met, assume the sentence is in the present perfect tense
    tense = 'present_perfect';
end
```

