  app.useGlobalGuards(new PermissionGuard());

  app.useModule(TypeOrmModule.forRoot({
    type: 'mysql',
    host: 'localhost',
    port: 3306,
    username: 'root',
    password: 'password',
    database: 'mydatabase',
    entities: ['dist/**/*.entity{.ts,.js}'],
    synchronize: true,
  }));

  app.useModule(TypeOrmModule.forFeature([Permission]));

  await app.listen(3000);
}

bootstrap();
```

