function smoothMap(x) {
  // Smooth start
  if (x <= 0.25) {
    return x * 4;
  }

  // Linear range
  if (x >= 0.75 && x <= 0.85) {
    return x - 0.5;
  }

  // Smooth end
  if (x > 0.85) {
    return 1 - (x - 0.85) * 4;
  }

  return x;
}
