Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key-value matches the string key:

```javascript
function getNestedEntries(obj, key) {
  const entries = [];

  function traverse(obj, path) {
    for (const key in obj) {
      if (path.includes(key)) {
        entries.push({ key, value: obj[key] });
      } else {
        traverse(obj[key], `${path}.${key}`);
      }
    }
  }

  traverse(obj, key);
  return entries;
}

// Example usage
const obj = {
  a: {
    b: 1,
    c: {
      d: 2,
      e: 3,
    },
  },
  f: 4,
};

const key = 'c.d';
const result = getNestedEntries(obj, key);
console.log(result); // Output: [{ key: 'c.d', value: 2 }]
```

Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key-value matches the string key:

```javascript
function getObjectEntries(object, keyPath) {
  const keys = keyPath.split('.');
  let currentObject = object;

  for (const key of keys) {
    if (!currentObject[key]) {
      return [];
    }
    currentObject = currentObject[key];
  }

  return Object.entries(currentObject);
}

// Example usage
const object = {
  a: {
    b: 'c',
    d: 'e',
  },
  f: 'g',
};

const keyPath = 'a.b';
const result = getObjectEntries(object, keyPath);
console.log(result); // Output: [['b', 'c']]
```

Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key value matches the string key:

```javascript
function getMatchingEntries(obj, str) {
  const entries = [];

  Object.entries(obj).forEach(([key, value]) => {
    if (key === str || obj[str] === value) {
      entries.push({ key, value });
    } else if (typeof value === 'object') {
      entries.push(...getMatchingEntries(value, str));
    }
  });

  return entries;
}

const obj = {
  a: 1,
  b: { c: 2 },
  d: [3, { e: 4 }],
};

const str = 'b';

const matchingEntries = getMatchingEntries(obj, str);
console.log(matchingEntries); // Output: [{ key: 'b', value: { c: 2 } }]
```

Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an option where the nested key value matches the string key:

```javascript
function getNestedValue(obj, path) {
  const keys = path.split('.');
  let value = obj;

  for (const key of keys) {
    if (!value[key]) {
      return undefined;
    }
    value = value[key];
  }

  return value;
}

function filterOption(options, key, value) {
  return options.filter(option => getNestedValue(option, key) === value);
}
```

You can use this function like this:

```javascript
const options = [
  { name: 'Option 1', value: 'apple' },
  { name: 'Option 2', value: 'banana' },
  { name: 'Option 3', value: 'orange' }
];

const key = 'value';
const value = 'apple';

const filteredOptions = filterOption(options, key, value);
console.log(filteredOptions); // Output: [{ name: 'Option 1', value: 'apple' }]
```

Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key value matches the string key:

```javascript
function getObjectEntries(obj, key) {
  const keys = key.split(".");
  const result = [];

  function traverse(obj, keys) {
    if (keys.length === 0) {
      result.push(obj);
      return;
    }

    const key = keys.shift();
    if (obj[key] !== undefined) {
      traverse(obj[key], keys);
    }
  }

  traverse(obj, keys);
  return result;
}
```

You can use this function like this:

```javascript
const obj = {
  a: {
    b: 1,
    c: 2,
  },
  d: 3,
};

const key = "a.b";
const entries = getObjectEntries(obj, key);
console.log(entries); // Output: [ { b: 1, c: 2 } ]
```

