Here's a simple React component using the useHooks library to convert between different temperature units:

```javascript
import { useState } from 'react';
import { useHooks } from 'use-hooks';

const TemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius');

  const handleInputChange = (event) => {
    setTemperature(parseFloat(event.target.value));
  };

  const handleUnitChange = (event) => {
    setUnit(event.target.value);
  };

  const { celsiusToFahrenheit, fahrenheitToCelsius } = useHooks({
    celsiusToFahrenheit: (celsius) => celsius * 1.8 + 32,
    fahrenheitToCelsius: (fahrenheit) => (fahrenheit - 32) / 1.8,
  });

  const convertedTemperature = unit === 'celsius' ? celsiusToFahrenheit(temperature) : fahrenheitToCelsius(temperature);

  return (
    <div>
      <label htmlFor="temperature">Temperature:</label>
      <input type="number" id="temperature" value={temperature} onChange={handleInputChange} />
      <label htmlFor="unit">Unit:</label>
      <select id="unit" value={unit} onChange={handleUnitChange}>
        <option value="celsius">Celsius</option>
        <option value="fahrenheit">Fahrenheit</option>
      </select>
      <p>Converted temperature: {convertedTemperature.toFixed(2)} {unit === 'celsius' ? '°C' : '°F'}</p>
    </div>
  );
};

export default TemperatureConverter;
```

