import datetime

class PomodoroTimer:
    def __init__(self, productivity_level, work_style):
        self.productivity_level = productivity_level
        self.work_style = work_style
        self.optimal_interval_length = self.calculate_optimal_interval_length()
        self.max_intervals_per_day = self.calculate_max_intervals_per_day()
        self.work_intervals = self.schedule_work_intervals()

    def calculate_optimal_interval_length(self):
        return round(self.productivity_level * 25)

    def calculate_max_intervals_per_day(self):
        return int(datetime.timedelta(minutes=self.optimal_interval_length).total_seconds()) // 60

    def schedule_work_intervals(self):
        work_intervals = []
        if self.work_style == 'focused':
            for i in range(self.max_intervals_per_day):
                work_intervals.append(f"Work interval {i+1}: {self.optimal_interval_length} minutes")
                work_intervals.append("Short break: 5 minutes")
            work_intervals.pop()  # remove last short break
            work_intervals.append("Long break: 15 minutes")
        elif self.work_style == 'distracted':
            for i in range(self.max_intervals_per_day):
                work_intervals.append(f"Work interval {i+1}: {self.optimal_interval_length} minutes")
                work_intervals.append("Long break: 10 minutes")
            work_intervals.pop()  # remove last long break
            work_intervals.append("Short break: 3 minutes")
        return work_intervals

