```javascript
function createNewArray(inputArray) {
  const outputArray = [];

  for (const item of inputArray) {
    const randomize = item.randomize;
    let index = item.position - 1;

    if (randomize) {
      const minIndex = 0;
      const maxIndex = outputArray.length - 1;
      index = Math.floor(Math.random() * (maxIndex - minIndex + 1)) + minIndex;
    }

    outputArray[index] = item.name;
  }

  return outputArray;
}

