To identify the most common non-silent vowel and consonant combinations in a given text, you can use a combination of regular expressions and a hash table. Here's an example script in Python:

```python
import re

def count_vowel_consonant_combinations(text):
    vowels = 'aeiou'
    combinations = {}

    # Regular expression pattern to match non-silent vowels and consonants
    pattern = r'([^aeiou]|[aeiou])'

    # Iterate over each word in the text
    words = re.split(r'\s+', text)
    for word in words:
        # Iterate over each character in the word
        for char in word:
            # Check if the character is a vowel or a consonant
            if char in vowels:
                # If it's a vowel, check if there's a consonant before it
                if char != word[0]:
                    combination = f'{char}{word[0]}'
                    if combination in combinations:
                        combinations[combination] += 1
                    else:
                        combinations[combination] = 1
            else:
                # If it's a consonant, check if there's a vowel after it
                if char != word[-1]:
                    combination = f'{word[-1]}{char}'
                    if combination in combinations:
                        combinations[combination] += 1
                    else:
                        combinations[combination] = 1

    return combinations

# Test the function with a sample text
text = 'The quick brown fox jumps over the lazy dog.'
combinations = count_vowel_consonant_combinations(text)

# Print the most common combinations
print("Most common vowel-consonant combinations:")
for combination, count in combinations.items():
    print(f"{combination}: {count}")
```

