To use GridFS, you'll need to install the `gridfs-mongodb` package using npm:

```bash
npm install gridfs-mongodb
```

Then, you can use the following code to upload an image to GridFS:

```javascript
const fs = require('fs');
const gridfs = require('gridfs-mongodb');
const mongoClient = require('mongodb').MongoClient;

async function uploadImage(imageFile) {
  const client = new mongoClient('mongodb://localhost:27017', { useNewUrlParser: true, useUnifiedTopology: true });
  await client.connect();

  const db = client.db('your_database_name');
  const gridFs = gridfs(db);

  const fileStream = fs.createReadStream(imageFile);
  const writeStream = gridFs.createWriteStream({ filename: imageFile });

  fileStream.pipe(writeStream);

  await new Promise((resolve, reject) => {
    writeStream.on('finish', resolve);
    writeStream.on('error', reject);
  });

  console.log('Image uploaded successfully!');
  await client.close();
}

uploadImage('path/to/your/image.jpg');
```

Replace `'your_database_name'` with the name of your MongoDB database.

