# Define function to check if a given SID is present in the SIDHistory of any user or group in the domain
function CheckSIDInSIDHistory {
    param(
        [string]$sid
    )

    $domain = (Get-ADDomain).Name
    $users = Get-ADUser -Filter {SID -eq $sid} -Properties MemberOf
    $groups = Get-ADGroup -Filter {SID -eq $sid} -Properties MemberOf

    if ($users.Count -gt 0) {
        return $true
    }

    if ($groups.Count -gt 0) {
        foreach ($group in $groups) {
            $groupMembers = Get-ADGroupMember -Identity $group.SamAccountName -Recursive

            foreach ($member in $groupMembers) {
                if ($member.SID -eq $sid) {
                    return $true
                }
            }
        }
    }

    return $false
}

# Define function to recursively check folder ACLs for SIDs in SIDHistory
function CheckFolderAclsForSidHistory {
    param(
        [string]$path
    )

    Get-Acl -Path $path | ForEach-Object {
        $acl = $_.Access

        foreach ($access in $acl) {
            if ($access.IdentityReference -match '^S-1-5-21-') {
                $sid = $access.IdentityReference

                if (CheckSIDInSIDHistory($sid)) {
                    Write-Host "ACL on $path references SID $sid, which occurs only in the SIDHistory of a user or group in the domain."
                }
            }
        }
    }

    Get-ChildItem -Path $path -Directory | ForEach-Object {
        CheckFolderAclsForSidHistory($_.FullName)
    }
}

