# Define the function to check ACLs for SIDs in SIDHistory
function CheckSidInSidHistory($folderPath) {
    $acl = Get-Acl -Path $folderPath
    foreach ($access in $acl.Access) {
        if ($access.IdentityReference -match '^S-(?<sid>\w+)$') {
            $sid = $matches['sid']
            $user = Get-ADUser -Filter "SIDHistory -eq '$sid'" -Properties SIDHistory
            if ($user) {
                Write-Host "SID $sid found in SIDHistory of user/group $($user.SamAccountName)"
            } else {
                Write-Host "SID $sid not found in SIDHistory of any user/group in the domain"
            }
        }
    }
}

# Define the root folder to start the recursion
$rootFolder = "C:\Your_Root_Folder"

# Recursively check folders for SIDs in SIDHistory
function RecursiveCheck($folderPath) {
    CheckSidInSidHistory($folderPath)
    foreach ($subFolder in (Get-ChildItem -Path $folderPath -Directory)) {
        RecursiveCheck($subFolder.FullName)
    }
}

# Start the recursion
RecursiveCheck($rootFolder)
```

